import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        InputStreamReader isr = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(isr);
        PrintWriter pw = new PrintWriter(System.out);
        AntiPalindrome ap = new AntiPalindrome();
        ap.process(br, pw);
        pw.close();
    }

    static class AntiPalindrome {
        public void process(BufferedReader br, PrintWriter pw) throws IOException {
            int N = Integer.parseInt(br.readLine());
            int[] freq = new int[26];
            int moves = 0;
            String sLine = br.readLine();
            char[] sChars = sLine.toCharArray();
            String[] costStrings = br.readLine().split(" ");
            int[] costs = new int[N];
            int totalCost = 0;
            for (int i = 0; i < N; i++) {
                costs[i] = Integer.parseInt(costStrings[i]);
                totalCost += costs[i];
            }
            for (int i = 0; i < N / 2; i++) {
                if (sChars[i] == sChars[N - i - 1]) {
                    freq[sChars[i] - 'a']++;
                    moves++;
                    totalCost -= Math.min(costs[i], costs[N - i - 1]);
                }
            }
            for (int ch = 0; ch < 26; ch++) {
                if (freq[ch] > moves / 2) {
                    int excess = freq[ch] * 2 - moves;
                    List<Integer> positions = new ArrayList<>();
                    for (int j = 0; j < N / 2; j++) {
                        if (sChars[j] != sChars[N - j - 1]) {
                            if (sChars[j] - 'a' != ch && sChars[N - j - 1] - 'a' != ch) {
                                positions.add(Math.min(costs[j], costs[N - j - 1]));
                            }
                        }
                    }
                    Collections.sort(positions);
                    for (int j = 0; j < Math.min(excess, positions.size()); j++) {
                        totalCost -= positions.get(j);
                    }
                }
            }
            pw.println(totalCost);
        }
    }
}
